    files = scoped_files(root, scope)
    declared = scope.get("declared_identifiers", [])
    findings = generality.scan_terms(
        root, files, scope["organization_terms"], declared=declared
    )
    exceptions = {entry["path"] for entry in scope.get("exceptions", [])}
    failures = [
        _fail(
            f"{finding['path']}#{finding['term_id']}#{finding['location']}",
            f"organization_name_in_product_surface_x{finding['count']}",
            "organization_scan",
        )
        for finding in findings
        if finding["path"] not in exceptions
    ]
    # A declaration that no longer matches reality is itself a finding.
    for identifier_id, path, code in generality.check_declared_identifiers(
        root, declared
    ):
        failures.append(_fail(f"{path}#{identifier_id}", code, "organization_scan"))
    diagnostics = [f"scanned_files={len(files)}"]
    for term_id in generality.pending_terms(scope["organization_terms"]):
        diagnostics.append(f"organization_term_pending_owner_input={term_id}")
    for entry in declared:
        if entry.get("owner") == "pending_owner_decision":
            diagnostics.append(
                f"declared_identifier_pending_owner_decision={entry['identifier_id']}"
            )
    return failures, diagnostics

def build_cause_signature(
    *, block_id, check_id, runner_kind, parser, structured
):
    """Build a versioned structural signature, or ``None`` if impossible."""
    if not isinstance(structured, dict):
        return None
    outcome = structured.get("outcome")
    if outcome not in FAILING_OUTCOMES:
        # Passed, timed out or otherwise structurally opaque.
        return None
    if structured.get("structural") is False:
        # Exit code only, missing report, unreadable output: no reliable cause.
        return None
    failures = structured.get("failures") or []
    diagnostics = structured.get("diagnostics") or []
    if not failures and not diagnostics:
        return None
    try:
        normalised_failures = _normalised_failures(failures)
    except CauseSignatureError:
        return None

    categories = sorted(
        {failure["category"] for failure in normalised_failures}
    )
    classes = sorted(
        {failure["class"] for failure in normalised_failures if failure["class"]}
    )
    elements = {
        "block_id": normalize_token(block_id),
        "check_id": normalize_token(check_id),
        "runner_kind": normalize_token(runner_kind),
        "parser": normalize_token(parser),
        "outcome": outcome,
        "failure_count": len(normalised_failures),
        "failure_categories": categories,
        "failure_classes": classes,
        "failures": normalised_failures,
        "diagnostics": sorted(
            normalize_token(diagnostic) for diagnostic in diagnostics
        ),
    }
    sanitize.assert_clean(elements, "$cause_signature")
    payload = {
        "signature_version": CAUSE_SIGNATURE_VERSION,
        "elements": elements,
    }
    digest = hashlib.sha256(
        json.dumps(payload, sort_keys=True, ensure_ascii=True).encode("utf-8")
    ).hexdigest()
    payload["digest"] = digest
    return payload

